class StrongestExtensionFinder:
    @staticmethod
    def strength(ext: str) -> int:
        # difference between count of uppercase and lowercase letters
        upper = sum(1 for c in ext if c.isupper())
        lower = sum(1 for c in ext if c.islower())
        return abs(upper - lower)

    @staticmethod
    def strongest(class_name: str, extensions: list) -> str:
        best = None
        best_strength = -1
        for ext in extensions:
            s = StrongestExtensionFinder.strength(ext)
            if s > best_strength:
                best_strength = s
                best = ext
        if best is None:
            return f"{class_name}"
        return f"{class_name}.{best}"

