class Strongest_Extension:
    @staticmethod
    def strongest(class_name, extensions):
        def strength(s):
            upper = sum(1 for c in s if c.isupper())
            lower = sum(1 for c in s if c.islower())
            return upper - lower

        # Compute maximum strength among all extensions
        max_strength = max(strength(ext) for ext in extensions)

        # Return the first extension with this maximum strength, prefixed by class name
        for ext in extensions:
            if strength(ext) == max_strength:
                return f"{class_name}.{ext}"
        return None

