class Extension:
    def __init__(self, name, cap_sm_disparity):
        self.name = name
        self.cap_sm_disparity = cap_sm_disparity

    def __repr__(self):
        return f"{self.name}:{self.cap_sm_disparity}"

class ClassExt:
    def __init__(self, items):
        self.items = items  # list of Extension

    def strongest_extension(self):
        if not self.items:
            return None
        # Return the extension with the highest CAP-SM disparity
        strongest = max(self.items, key=lambda e: e.cap_sm_disparity)
        return strongest

