import sys

text = sys.stdin.read()
if not text or text.strip() == "":
    print({})
else:
    words = text.split()
    lowers = [w.lower() for w in words]
    counts = Counter(lowers)
    if not counts:
        print({})
    else:
        maxf = max(counts.values())
        top = {w: maxf for w, f in counts.items() if f == maxf}
